"""
LLM-Powered Strategy Generator

Uses large language models to:
1. Generate novel trading strategy hypotheses
2. Convert hypotheses to executable Python code
3. Optimize existing strategies with reasoning
4. Analyze market conditions for regime detection
"""

import asyncio
import json
import re
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, List, Optional, Tuple
from uuid import uuid4
from abc import ABC, abstractmethod


@dataclass
class StrategyHypothesis:
    """A trading strategy hypothesis generated by LLM."""
    hypothesis_id: str
    name: str
    description: str
    market_condition: str  # When this strategy should work
    expected_edge: str  # Why this should be profitable
    risk_factors: List[str]
    indicators_used: List[str]
    entry_logic: str
    exit_logic: str
    position_sizing: str
    generated_code: Optional[str] = None
    confidence: float = 0.5
    timestamp: datetime = field(default_factory=datetime.utcnow)


@dataclass
class CodeGenerationResult:
    """Result of strategy code generation."""
    success: bool
    code: str
    strategy_class_name: str
    parameters: Dict[str, Any]
    validation_errors: List[str] = field(default_factory=list)


@dataclass
class MarketRegimeAnalysis:
    """LLM analysis of market regime."""
    regime: str  # 'trending', 'ranging', 'volatile', 'calm'
    confidence: float
    supporting_factors: List[str]
    recommended_strategies: List[str]
    risk_level: str  # 'low', 'medium', 'high'
    analysis_text: str


class LLMProvider(ABC):
    """Abstract LLM provider interface."""

    @abstractmethod
    async def generate(self, prompt: str, **kwargs) -> str:
        pass

    @abstractmethod
    async def generate_json(self, prompt: str, schema: Dict) -> Dict:
        pass


