class LLMStrategyGenerator:
    """
    Main LLM strategy generation engine.

    Generates novel trading strategies using LLM reasoning.
    """

    def __init__(self, provider: LLMProvider):
        self.provider = provider
        self.templates = StrategyPromptTemplates()
        self._generated_hypotheses: List[StrategyHypothesis] = []
        self._generated_code: Dict[str, CodeGenerationResult] = {}

    async def generate_hypothesis(
        self,
        market_context: Dict[str, Any]
    ) -> StrategyHypothesis:
        """Generate a novel strategy hypothesis."""
        prompt = self.templates.HYPOTHESIS_GENERATION.format(
            market_context=json.dumps(market_context, indent=2)
        )

        response = await self.provider.generate(prompt)

        # Parse response (would need actual JSON parsing)
        hypothesis = self._parse_hypothesis(response)
        self._generated_hypotheses.append(hypothesis)

        return hypothesis

    async def generate_code(
        self,
        hypothesis: StrategyHypothesis
    ) -> CodeGenerationResult:
        """Generate executable Python code from hypothesis."""
        prompt = self.templates.CODE_GENERATION.format(
            hypothesis=json.dumps({
                'name': hypothesis.name,
                'description': hypothesis.description,
                'entry_logic': hypothesis.entry_logic,
                'exit_logic': hypothesis.exit_logic,
                'position_sizing': hypothesis.position_sizing,
                'indicators_used': hypothesis.indicators_used
            }, indent=2)
        )

        response = await self.provider.generate(prompt)

        # Extract and validate code
        result = self._extract_and_validate_code(response, hypothesis)
        self._generated_code[hypothesis.hypothesis_id] = result

        if result.success:
            hypothesis.generated_code = result.code

        return result

    async def optimize_strategy(
        self,
        strategy_code: str,
        parameters: Dict[str, Any],
        performance_metrics: Dict[str, float]
    ) -> Dict[str, Any]:
        """Get LLM suggestions for strategy optimization."""
        prompt = self.templates.STRATEGY_OPTIMIZATION.format(
            strategy_code=strategy_code,
            parameters=json.dumps(parameters, indent=2),
            performance_metrics=json.dumps(performance_metrics, indent=2)
        )

        response = await self.provider.generate(prompt)

        # Parse optimization suggestions
        return self._parse_optimization_response(response)

    async def analyze_market_regime(
        self,
        market_data: Dict[str, Any]
    ) -> MarketRegimeAnalysis:
        """Analyze current market regime."""
        prompt = self.templates.REGIME_ANALYSIS.format(
            market_data=json.dumps(market_data, indent=2)
        )

        response = await self.provider.generate(prompt)

        return self._parse_regime_analysis(response)

    async def batch_generate_hypotheses(
        self,
        market_context: Dict[str, Any],
        count: int = 10
    ) -> List[StrategyHypothesis]:
        """Generate multiple strategy hypotheses."""
        tasks = [
            self.generate_hypothesis(market_context)
            for _ in range(count)
        ]
        return await asyncio.gather(*tasks)

    def _parse_hypothesis(self, response: str) -> StrategyHypothesis:
        """Parse LLM response into StrategyHypothesis."""
        # Would parse actual JSON from LLM
        # Placeholder implementation
        return StrategyHypothesis(
            hypothesis_id=str(uuid4()),
            name="LLM Generated Strategy",
            description="Strategy generated by LLM",
            market_condition="Trending markets",
            expected_edge="Momentum capture",
            risk_factors=["Whipsaws", "Trend reversals"],
            indicators_used=["SMA", "RSI"],
            entry_logic="Buy when fast SMA crosses above slow SMA and RSI < 70",
            exit_logic="Sell when fast SMA crosses below slow SMA or RSI > 80",
            position_sizing="Risk 2% of portfolio per trade",
            confidence=0.6
        )

    def _extract_and_validate_code(
        self,
        response: str,
        hypothesis: StrategyHypothesis
    ) -> CodeGenerationResult:
        """Extract Python code from LLM response and validate it."""
        # Extract code block
        code_match = re.search(r'```python\n(.*?)```', response, re.DOTALL)
        if code_match:
            code = code_match.group(1)
        else:
            code = response

        # Basic validation
        errors = []

        if 'class ' not in code:
            errors.append("No class definition found")

        if 'BaseStrategy' not in code:
            errors.append("Does not inherit from BaseStrategy")

        if 'def initialize' not in code:
            errors.append("Missing initialize method")

        if 'def generate_signals' not in code:
            errors.append("Missing generate_signals method")

        # Extract class name
        class_match = re.search(r'class\s+(\w+)\s*\(', code)
        class_name = class_match.group(1) if class_match else "UnknownStrategy"

        # Extract parameters (look for self.parameters.get calls)
        param_matches = re.findall(r"self\.parameters\.get\(['\"](\w+)['\"],\s*([^)]+)\)", code)
        parameters = {name: self._parse_default(default) for name, default in param_matches}

        return CodeGenerationResult(
            success=len(errors) == 0,
            code=code,
            strategy_class_name=class_name,
            parameters=parameters,
            validation_errors=errors
        )

    def _parse_default(self, default_str: str) -> Any:
        """Parse default parameter value from string."""
        default_str = default_str.strip()
        try:
            return eval(default_str)
        except:
            return default_str

    def _parse_optimization_response(self, response: str) -> Dict[str, Any]:
        """Parse optimization suggestions from LLM."""
        # Would parse actual JSON
        return {
            'analysis': 'Strategy analysis',
            'parameter_changes': {},
            'logic_improvements': [],
            'expected_improvement': 'Unknown'
        }

    def _parse_regime_analysis(self, response: str) -> MarketRegimeAnalysis:
        """Parse market regime analysis from LLM."""
        # Would parse actual JSON
        return MarketRegimeAnalysis(
            regime='trending',
            confidence=0.7,
            supporting_factors=['Strong momentum', 'Low volatility'],
            recommended_strategies=['trend_following', 'momentum'],
            risk_level='medium',
            analysis_text='Market analysis placeholder'
        )


class AgentStrategyGenerator:
    """
    Strategy generator for competitive agents.

    Each agent uses this to generate novel strategies during competition.
    """

    def __init__(
        self,
        agent_id: str,
        llm_generator: LLMStrategyGenerator
    ):
        self.agent_id = agent_id
        self.llm = llm_generator
        self.generated_strategies: List[StrategyHypothesis] = []

    async def generate_strategy_for_regime(
        self,
        regime: str,
        market_context: Dict[str, Any]
    ) -> Optional[CodeGenerationResult]:
        """Generate a strategy optimized for a specific market regime."""
        # Add regime context
        context = {
            **market_context,
            'target_regime': regime,
            'agent_specialization': self._get_agent_specialization()
        }

        # Generate hypothesis
        hypothesis = await self.llm.generate_hypothesis(context)

        if hypothesis.confidence < 0.5:
            return None

        # Generate code
        result = await self.llm.generate_code(hypothesis)

        if result.success:
            self.generated_strategies.append(hypothesis)

        return result

    def _get_agent_specialization(self) -> str:
        """Get this agent's specialization based on ID."""
        # Different agents specialize in different strategy types
        specializations = [
            'trend_following',
            'mean_reversion',
            'momentum',
            'volatility',
            'multi_factor'
        ]
        # Use agent ID to determine specialization
        idx = hash(self.agent_id) % len(specializations)
        return specializations[idx]

    async def improve_strategy(
        self,
        strategy_code: str,
        performance: Dict[str, float]
    ) -> Optional[str]:
        """Improve a strategy based on performance feedback."""
